'use strict';

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'
  })[character]);
}

function nonEmpty(value) {
  return typeof value === 'string' && value.length > 0;
}

function external(value) {
  if (!nonEmpty(value)) return false;
  try {
    const url = new URL(value);
    return url.protocol === 'http:' || url.protocol === 'https:';
  } catch (_) {
    return false;
  }
}

function renderKnowledgePage(article) {
  if (!article || !nonEmpty(article.title) || !nonEmpty(article.description) ||
      !nonEmpty(article.published) || !nonEmpty(article.slug) ||
      typeof article.minutes !== 'number' || !Number.isFinite(article.minutes) || article.minutes < 0 ||
      !Array.isArray(article.paragraphs) || !article.paragraphs.every((item) => typeof item === 'string') ||
      !Array.isArray(article.tags) || !article.tags.every((item) => typeof item === 'string')) {
    throw new TypeError('invalid article');
  }

  const e = escapeHtml;
  const image = article.image && nonEmpty(article.image.src) && nonEmpty(article.image.alt) &&
    nonEmpty(article.image.credit) && nonEmpty(article.image.source)
    ? '<figure><img src="' + e(article.image.src) + '" alt="' + e(article.image.alt) +
      '" loading="lazy"><figcaption>' + e(article.image.credit) + ' — ' +
      e(article.image.source) + '</figcaption></figure>'
    : '';
  const paragraphs = article.paragraphs.map((text) => '<p>' + e(text) + '</p>').join('');
  const tags = article.tags.map((tag) => '<a href="/knowledge?tag=' +
    tag + '">' + e(tag) + '</a>').join('');
  const outbound = external(article.externalUrl)
    ? '<a href="' + e(article.externalUrl) + '" target="_blank" rel="noopener noreferrer">External source</a>'
    : '';

  return '<!doctype html><html lang="en"><head><meta charset="utf-8">' +
    '<meta name="viewport" content="width=device-width,initial-scale=1">' +
    '<title>' + e(article.title) + '</title><meta name="description" content="' +
    e(article.description) + '"><meta name="keywords" content="' +
    e(article.tags.join(', ')) + '"></head><body><a href="/knowledge">Back to knowledge</a>' +
    '<article>' + image + '<h1>' + e(article.title) + '</h1><time>' +
    e(article.published) + '</time><span>' + e(article.minutes) + ' min read</span>' +
    paragraphs + '<nav aria-label="Tags">' + tags + '</nav>' + outbound +
    '<section id="discussion" data-thread="' + e(article.slug) +
    '" aria-label="Discussion"></section></article></body></html>';
}

module.exports = { renderKnowledgePage };

