'use strict';

const assert = require('node:assert/strict');
const api = require('./solution');

assert.deepEqual(Object.keys(api).sort(), ['renderKnowledgePage']);
const { renderKnowledgePage } = api;
assert.equal(typeof renderKnowledgePage, 'function');

const article = {
  title: 'A <Guide> & "Notes"',
  description: 'Learn <fast> & safely "today"',
  published: '2026-08-28 & later',
  slug: 'thread<&"',
  minutes: 0,
  paragraphs: ['First <paragraph> & more.', 'Second "paragraph".'],
  tags: ['web & api', '<script>'],
  image: {
    src: 'https://img.example/a?x=1&y="2"',
    alt: 'Alt <text> & "quote"',
    credit: 'Credit & Co',
    source: 'Source <One>'
  },
  externalUrl: 'https://example.com/read?x=1&y=2'
};
const before = JSON.stringify(article);
const html = renderKnowledgePage(article);
assert.equal(JSON.stringify(article), before);
assert.match(html, /^<!DOCTYPE html>/i);
assert.match(html, /<meta[^>]+charset=["']?UTF-8/i);
assert.match(html, /<meta[^>]+name=["']viewport["']/i);
assert.ok(html.includes('<title>A &lt;Guide&gt; &amp; &quot;Notes&quot;</title>'));
assert.match(html, /<meta[^>]+name=["']description["'][^>]+content=["']Learn &lt;fast&gt; &amp; safely &quot;today&quot;["']/i);
assert.match(html, /<meta[^>]+name=["']keywords["'][^>]+content=["']web &amp; api, &lt;script&gt;["']/i);
assert.ok(html.includes('href="/knowledge"'));
assert.ok(html.includes('<article'));
assert.ok(html.includes('<h1>A &lt;Guide&gt; &amp; &quot;Notes&quot;</h1>'));
assert.ok(html.includes('<time'));
assert.ok(html.includes('2026-08-28 &amp; later'));
assert.ok(html.includes('0'));
assert.ok(html.includes('<p>First &lt;paragraph&gt; &amp; more.</p>'));
assert.ok(html.includes('<p>Second &quot;paragraph&quot;.</p>'));
assert.ok(html.indexOf('First &lt;paragraph&gt;') < html.indexOf('Second &quot;paragraph&quot;'));
assert.match(html, /<figure[\s\S]*<img[^>]+loading=["']lazy["'][^>]*>[\s\S]*<figcaption>[\s\S]*Credit &amp; Co[\s\S]*Source &lt;One&gt;[\s\S]*<\/figcaption>[\s\S]*<\/figure>/i);
assert.ok(html.includes('src="https://img.example/a?x=1&amp;y=&quot;2&quot;"'));
assert.ok(html.includes('alt="Alt &lt;text&gt; &amp; &quot;quote&quot;"'));
assert.ok(html.includes('href="/knowledge?tag=web%20%26%20api"'));
assert.ok(html.includes('href="/knowledge?tag=%3Cscript%3E"'));
assert.ok(html.indexOf('web%20%26%20api') < html.indexOf('%3Cscript%3E'));
assert.match(html, /<a[^>]+href=["']https:\/\/example\.com\/read\?x=1&amp;y=2["'][^>]+target=["']_blank["'][^>]+rel=["']noopener noreferrer["']/i);
assert.ok(html.includes('<section id="discussion" data-thread="thread&lt;&amp;&quot;" aria-label="Discussion"></section>'));
assert.ok(!html.includes('<script>'));

const minimal = {
  title: 'T', description: 'D', published: 'P', slug: 'S',
  minutes: 2.5, paragraphs: [], tags: [],
  image: { src: 'x', alt: '', credit: 'c', source: 's' },
  externalUrl: '/relative'
};
const minimalHtml = renderKnowledgePage(minimal);
assert.ok(!minimalHtml.includes('<figure'));
assert.ok(!minimalHtml.includes('target="_blank"'));
assert.ok(minimalHtml.includes('<section id="discussion" data-thread="S" aria-label="Discussion"></section>'));

for (const invalid of [
  null,
  {},
  { title: '', description: 'd', published: 'p', slug: 's', minutes: 1, paragraphs: [], tags: [] },
  { title: 't', description: 'd', published: 'p', slug: 's', minutes: -1, paragraphs: [], tags: [] },
  { title: 't', description: 'd', published: 'p', slug: 's', minutes: Infinity, paragraphs: [], tags: [] },
  { title: 't', description: 'd', published: 'p', slug: 's', minutes: 1, paragraphs: ['ok', 2], tags: [] },
  { title: 't', description: 'd', published: 'p', slug: 's', minutes: 1, paragraphs: [], tags: [null] }
]) {
  assert.throws(() => renderKnowledgePage(invalid), TypeError);
}

